defmodule JoobQ.Worker.FramesTest do
  use ExUnit.Case, async: true

  alias JoobQ.Worker.{Frames, Outcome}

  defmodule Handler do
    def perform(%{payload: payload}), do: pick(payload)
    defp pick(%{"ok" => value}), do: value
  end

  defp valid?(%{"file" => file, "line" => line, "function" => function}),
    do:
      is_binary(file) and file != "" and is_integer(line) and is_binary(function) and
        function != ""

  test "a failed run reports its frames innermost first, with arities and never the arguments" do
    outcome = Outcome.run(Handler, %JoobQ.Job{payload: %{"password" => "hunter2"}})

    assert %{"stack_frames" => [top | _rest], "raw_stacktrace" => raw} = outcome
    assert top["function"] == "JoobQ.Worker.FramesTest.Handler.pick/1"
    assert top["file"] =~ "frames_test.exs" and top["line"] > 0
    assert Enum.all?(outcome["stack_frames"], &valid?/1)
    assert raw =~ "pick/1"
    refute inspect(outcome) =~ "hunter2"
  end

  test "frames are bounded, cleaned, and odd ones are left out" do
    many = for n <- 1..80, do: {Mod, :fun, [n], [file: ~c"lib/mod.ex", line: n]}
    assert %{"stack_frames" => frames} = Frames.report(many)
    assert length(frames) == 50

    odd = [
      {Mod, :fun, 2, []},
      {Mod, :fun, 1, [file: "", line: -3]},
      {&String.upcase/1, ["s3cr3t"], [file: ~c"x.ex", line: 2]},
      :garbage,
      {Mod, :fun, 1, [file: <<0xFF, "\e[31m">>, line: 4]}
    ]

    assert %{"stack_frames" => frames, "raw_stacktrace" => raw} = Frames.report(odd)
    assert length(frames) == 4 and Enum.all?(frames, &valid?/1)
    assert Enum.map(frames, & &1["file"]) == ["nofile", "nofile", "x.ex", "�[31m"]
    assert Enum.map(frames, & &1["line"]) == [0, 0, 2, 4]
    refute raw =~ "s3cr3t" or Enum.any?(frames, &(&1["function"] =~ "s3cr3t"))
    assert String.valid?(raw)
    assert Frames.report([]) == %{} and Frames.report(nil) == %{}
  end

  test "a returned error carries no frames; a raise, an exit and a throw do" do
    refute Map.has_key?(Outcome.returned({:error, :timeout}), "stack_frames")

    for {kind, reason} <- [error: RuntimeError.exception("x"), exit: :gone, throw: :ball] do
      stack = [{Mod, :fun, 0, [file: ~c"a.ex", line: 1]}]

      assert %{"stack_frames" => [%{"function" => "Mod.fun/0"}]} =
               Outcome.caught(kind, reason, stack)
    end
  end

  test "a malformed location never raises: its file is \"nofile\" and the failure is still reported" do
    for location <- [
          [:bogus],
          [file: [-1], line: 1],
          [file: [0xD800], line: 2],
          [1 | 2],
          [file: [1 | 2]]
        ] do
      stack = [{Mod, :fun, [%{"password" => "hunter2"}], location}]
      assert %{"stack_frames" => [%{"file" => "nofile"} = frame]} = Frames.report(stack)
      assert frame["function"] == "Mod.fun/1"

      outcome = Outcome.caught(:error, RuntimeError.exception("boom"), stack)
      assert %{"error_class" => "RuntimeError", "stack_frames" => [_frame]} = outcome
      refute inspect(outcome) =~ "hunter2"
    end
  end
end
